<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'

type FarmerRequest = Record<string, string | string[]>
const router = useRouter()
const search = ref('')
const user = JSON.parse(localStorage.getItem('taste-user') ?? '{}') as { name?: string }
const request = ref<FarmerRequest | null>(JSON.parse(localStorage.getItem('taste-farmer-verification') ?? 'null'))
const flaggedUsers = ref<string[]>(JSON.parse(localStorage.getItem('taste-flagged-users') ?? '[]'))
const status = ref(String(request.value?.status ?? 'Pending'))
const pendingCount = computed(() => request.value && status.value === 'Pending' ? 1 : 0)
const approvedCount = computed(() => status.value === 'Approved' ? 1 : 0)
const flaggedCount = computed(() => flaggedUsers.value.length)
const matchesSearch = (record: unknown) => !search.value || JSON.stringify(record ?? {}).toLowerCase().includes(search.value.toLowerCase())
const requestId = computed(() => String(request.value?.userId ?? ''))
const requestFlagged = computed(() => Boolean(requestId.value && flaggedUsers.value.includes(requestId.value)))
function approveRequest() {
  if (!request.value || requestFlagged.value) return
  status.value = 'Approved'
  request.value.status = 'Approved'
  localStorage.setItem('taste-farmer-verification', JSON.stringify(request.value))
}
function reviewDocs() {
  const names = request.value?.documents
  window.alert(`Uploaded files: ${Array.isArray(names) ? names.join(', ') : names || 'No file names available'}`)
}
function toggleFlag(id: string) {
  if (!id) return
  flaggedUsers.value = flaggedUsers.value.includes(id)
    ? flaggedUsers.value.filter((flaggedId) => flaggedId !== id)
    : [...flaggedUsers.value, id]
  localStorage.setItem('taste-flagged-users', JSON.stringify(flaggedUsers.value))
}
function clearFlags() {
  flaggedUsers.value = []
  localStorage.setItem('taste-flagged-users', '[]')
}
function logout() { localStorage.removeItem('taste-user'); router.push('/login') }
</script>

<template>
  <main class="admin-page">
    <header class="admin-header"><button class="admin-logo" @click="logout">Taste</button><button class="admin-profile" aria-label="Log out" @click="logout"></button></header>
    <section class="admin-content"><h1>Welcome, {{ user.name || 'Admin' }}</h1>
      <div class="stat-grid"><article class="stat users"><h2>Total Users</h2><div class="user-total"><strong>42</strong><span>32 customers<br />10 farmers</span></div></article><article class="stat pending"><h2>Pending Requests</h2><strong>{{ pendingCount }}</strong></article><article class="stat approved"><h2>Approved Requests</h2><strong>{{ approvedCount }}</strong></article><article class="stat flagged"><h2>Flagged</h2><strong>{{ flaggedCount }}</strong></article></div>
      <div class="toolbar"><label class="user-search"><span aria-hidden="true">⌕</span><input v-model="search" placeholder="Search for users" /></label><button class="secondary-button" @click="clearFlags">Unselect All</button><button v-if="requestId" class="review-button" :disabled="requestFlagged" @click="approveRequest">Approve All</button></div>
      <article v-if="matchesSearch({ name: 'UserName', id: 'user-01' })" class="user-row"><span class="avatar"></span><div><strong>UserName</strong><small>Phnom Penh , Cambodia</small><small>(+855)12 345 678</small></div><span class="user-id-label">ID<br /><br />#user-01</span></article>
      <article v-if="request && matchesSearch(request)" class="user-row farmer-row"><span class="avatar"></span><div class="farmer-identity"><strong>Farmer</strong><small>{{ request.farmLocation || 'Phnom Penh , Cambodia' }}</small><small>{{ request.phone || '(+855)12 345 678' }}</small></div><div class="farmer-field id-field"><span>ID</span><strong>{{ request.userId || '#user-02' }}</strong></div><div class="farmer-field business-field"><span>Business name</span><strong>{{ request.businessName || 'Selling Fruits' }}</strong></div><div class="farmer-field farm-field"><span>Farm Location</span><strong>{{ request.farmLocation || 'Phnom Penh , Cambodia' }}</strong></div><div class="farmer-field status-field"><span>Status</span><strong class="request-status" :class="{ 'request-flagged': requestFlagged }">{{ requestFlagged ? 'Flagged' : status }}</strong></div><div class="row-actions"><label><input type="checkbox" :checked="status === 'Approved'" :disabled="requestFlagged" @change="approveRequest" /> Approve</label><button class="review-button" @click="reviewDocs">Review Docs</button></div><button class="flag-button request-flag-button" :class="{ flagged: requestFlagged }" @click="toggleFlag(requestId)">{{ requestFlagged ? 'Unflag User' : 'Flag as Sus' }}</button></article>
      <p v-else-if="!request" class="empty-state">No farmer verification requests yet.</p>
    </section>
  </main>
</template>

